{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello Alka जी आपको seller table chair set की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "ठीक है मैं Tanya बोल रही हूं IndiaMART से।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "हमारे पास कई अच्छे sellers available हैं जिनसे मैं अभी आपको connect करवाऊंगी।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "बस कुछ details confirm कर दीजिए।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "कितने piece चाहिए होंगे आपको?"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "पूछते।"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "समझ गई?"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "चलिए अब product type के बारे में बात कर लेते हैं।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "आपको table and chair set चाहिए या कुछ और?"
    },
    {
      "i": 10,
      "speaker": "caller",
      "text": "बारे में।"
    },
    {
      "i": 11,
      "speaker": "caller",
      "text": "नहीं नहीं बस वही चाहिए।"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "ठीक है?"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "ये आपको मैं seller details WhatsApp पे भेज दूंगी जिनसे आप details और price discuss कर सकते हैं।"
    },
    {
      "i": 14,
      "speaker": "caller",
      "text": "एक मुझे ना एक old मेरे को एक मैंने वो Dreamland से लिया हुआ था झूला।"
    },
    {
      "i": 15,
      "speaker": "caller",
      "text": "तो उसका ठीक है आप पूरी list दे दो।"
    },
    {
      "i": 16,
      "speaker": "caller",
      "text": "थोड़ा सा वो खराब हो रहा है तो उसको repair करवाना है उनसे।"
    },
    {
      "i": 17,
      "speaker": "bot",
      "text": "ठीक है आप पूरी list"
    },
    {
      "i": 18,
      "speaker": "bot",
      "text": "मैं repair में आपकी मदद नहीं कर पाऊँगी लेकिन मैं आपको नए sellers से connect कर सकती हूँ।"
    },
    {
      "i": 19,
      "speaker": "bot",
      "text": "IndiaMART चुनने के लिए धन्यवाद।"
    },
    {
      "i": 20,
      "speaker": "bot",
      "text": "आपका दिन शुभ हो।"
    },
    {
      "i": 21,
      "speaker": "caller",
      "text": "IndiaMART से"
    }
  ]
}
